-- Question: Compare length of stay in diabetes with versus without CKD. Shape: ckd_group, n, avg_los. Assumption: valid dates only. Concepts: CTE, EXISTS, CASE.
WITH diabetic AS (SELECT DISTINCT e.encounter_id,e.admission_date,e.discharge_date FROM encounters e JOIN encounter_diagnoses ed ON ed.encounter_id=e.encounter_id JOIN diagnoses d ON d.diagnosis_id=ed.diagnosis_id WHERE d.diagnosis_code='E11.9') SELECT CASE WHEN EXISTS(SELECT 1 FROM encounter_diagnoses x JOIN diagnoses d ON d.diagnosis_id=x.diagnosis_id WHERE x.encounter_id=diabetic.encounter_id AND d.diagnosis_code='N18.9') THEN 'CKD' ELSE 'No CKD' END ckd_group,COUNT(*) n,AVG(julianday(discharge_date)-julianday(admission_date)) avg_los FROM diabetic WHERE discharge_date>=admission_date GROUP BY ckd_group;
